    if len(lines) != N + 2:
        print(-1)
        return

    positive_count = 0
    negative_count = 0
    word_count = {}  # 字典，键为单词，值为 [正类出现次数, 负类出现次数]

    # 遍历每篇文档
    for i in range(1, N+1):
        line = lines[i]
        # 如果存在制表符，则用制表符分割；否则按空格拆分，第一个单词为标签
