            label, text = line.split("\t", 1)
        else:
            parts = line.split()
            if len(parts) < 2:
                print(-1)
                return
            label = parts[0]
            text = " ".join(parts[1:])

        if label == "positive":
            positive_count += 1
            is_positive = True
        elif label == "negative":
            negative_count += 1
            is_positive = False
        else:
            print(-1)
            return

        # 用集合保证每篇文档中每个单词只计一次
        words = set(text.split())
        for word in words:
            if word not in word_count:
                word_count[word] = [0, 0]
            if is_positive:
                word_count[word][0] += 1
            else:
                word_count[word][1] += 1

    total = positive_count + negative_count
    features = []
    # 计算每个单词的卡方值
    for word, counts in word_count.items():
        A = counts[0]  # 正类中出现该单词
        B = counts[1]  # 负类中出现该单词
        C = positive_count - A  # 正类中未出现该单词
        D = negative_count - B  # 负类中未出现该单词

        row1 = A + B  # 单词出现的总文档数
        row2 = C + D  # 单词未出现的文档数
        col1 = positive_count
        col2 = negative_count

        chi = 0.0
        # 计算每个单元格的期望频数E并累加贡献
        if row1 > 0 and col1 > 0:
            E = row1 * col1 / total
            if E > 0:
                chi += (A - E) ** 2 / E
        if row1 > 0 and col2 > 0:
            E = row1 * col2 / total
            if E > 0:
                chi += (B - E) ** 2 / E
        if row2 > 0 and col1 > 0:
            E = row2 * col1 / total
            if E > 0:
                chi += (C - E) ** 2 / E
        if row2 > 0 and col2 > 0:
            E = row2 * col2 / total
            if E > 0:
                chi += (D - E) ** 2 / E

        features.append((word, chi))

    # 按照卡方值从大到小排序，若卡方值相同则按字母序升序
    features.sort(key=lambda x: (-x[1], x[0]))

    try:
        k = int(lines[-1])
    except:
        print(-1)
        return

    # 输出前k个特征
    for i in range(min(k, len(features))):
        print(features[i][0])

if __name__ == "__main__":
    main()

