### Python

```python
# -*- coding: utf-8 -*-
import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        print(-1)
        return

    try:
        N = int(lines[0])
    except:
        print(-1)
        return

    # 需要 N 行文档 + 1 行 k 值
    if len(lines) != N + 2:
        print(-1)
        return

    positive_count = 0
    negative_count = 0
    word_counts = {}  # key: word, value: [A, B]

    for i in range(1, N + 1):
        line = lines[i]
        if "\t" in line:
            label, text = line.split("\t", 1)
        else:
            # 兼容无制表符的情况：第一个单词为标签，其余为文本
            parts = line.split()
            if len(parts) < 2:
                print(-1)
                return
            label = parts[0]
            text = " ".join(parts[1:])

        if label == "positive":
            positive_count += 1
            is_positive = True
        elif label == "negative":
            negative_count += 1
            is_positive = False
        else:
            print(-1)
            return

        # 词袋处理：集合去重
        words = set(text.split())
        for word in words:
            if word not in word_counts:
                word_counts[word] = [0, 0]
            if is_positive:
                word_counts[word][0] += 1
            else:
                word_counts[word][1] += 1

    total = positive_count + negative_count
    features = []

    for word, (A, B) in word_counts.items():
        C = positive_count - A
        D = negative_count - B

        row1 = A + B  # 含有该单词的文档总数
        row2 = C + D  # 不含该单词的文档总数
        col1 = positive_count
        col2 = negative_count

        S = 0.0
        # 计算四个单元格对 S 的贡献
        if row1 > 0 and col1 > 0:
            E = row1 * col1 / total
            if E > 0:
                S += (A - E) ** 2 / E
        if row1 > 0 and col2 > 0:
            E = row1 * col2 / total
            if E > 0:
                S += (B - E) ** 2 / E
        if row2 > 0 and col1 > 0:
            E = row2 * col1 / total
            if E > 0:
                S += (C - E) ** 2 / E
        if row2 > 0 and col2 > 0:
            E = row2 * col2 / total
            if E > 0:
                S += (D - E) ** 2 / E

        features.append((word, S))

    # 按 S 降序，相同时按单词字典序升序
    features.sort(key=lambda x: (-x[1], x[0]))

    try:
        k = int(lines[-1])
    except:
        print(-1)
        return

    out_count = min(k, len(features))
    for i in range(out_count):
        print(features[i][0])

if __name__ == "__main__":
    main()
